import React, { useState, useRef, useEffect } from 'react';
import { toPng } from 'html-to-image';

// Predefined greeting templates
const GREETING_TEMPLATES = [
  {
    id: 'diwali',
    name: 'Diwali',
    background: 'data:image/jpeg;base64,',
    gradient: 'from-orange-500 to-yellow-500',
    defaultMessage: 'Wishing you a Happy and Prosperous Diwali!'
  },
  {
    id: 'holi',
    name: 'Holi',
    background: 'data:image/jpeg;base64,',
    gradient: 'from-pink-500 to-purple-500',
    defaultMessage: 'Happy Holi! May your life be filled with colors!'
  },
  {
    id: 'newyear',
    name: 'New Year 2026',
    background: 'data:image/jpeg;base64,',
    gradient: 'from-blue-500 to-indigo-500',
    defaultMessage: 'Happy New Year 2026! Wishing you success and happiness!'
  },
  {
    id: 'christmas',
    name: 'Christmas',
    background: 'https://images.unsplash.com/photo-1543589077-47d81606c1bf',
    gradient: 'from-red-500 to-green-500',
    defaultMessage: 'Merry Christmas! May the joy of the season be with you!'
  }
];

interface GreetingData {
  type: string;
  businessName: string;
  message: string;
  logo: string | null;
  showRefrens: boolean;
}

const GreetingsPage: React.FC = () => {
  const [selectedTemplate, setSelectedTemplate] = useState(GREETING_TEMPLATES[2]); // Default to New Year
  const [greetingData, setGreetingData] = useState<GreetingData>({
    type: 'newyear',
    businessName: 'Mahesh Solution',
    message: GREETING_TEMPLATES[2].defaultMessage,
    logo: null,
    showRefrens: true
  });
  const [previewImages, setPreviewImages] = useState<string[]>([]);

  console.log(previewImages);
  
  const [isGenerating, setIsGenerating] = useState(false);
  
  const greetingCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Generate preview images for all templates
  useEffect(() => {
    generatePreviews();
  }, []);

  const generatePreviews = async () => {
    // For demo purposes, we'll use the template backgrounds as previews
    // In production, you'd generate actual cards with default data
    const previews = GREETING_TEMPLATES.map(template => template.background);
    setPreviewImages(previews);
  };

  const handleTemplateChange = (templateId: string) => {
    const template = GREETING_TEMPLATES.find(t => t.id === templateId) || GREETING_TEMPLATES[0];
    setSelectedTemplate(template);
    setGreetingData(prev => ({
      ...prev,
      type: templateId,
      message: template.defaultMessage
    }));
  };

  const handleInputChange = (field: keyof GreetingData, value: string | boolean) => {
    setGreetingData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleLogoUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setGreetingData(prev => ({
          ...prev,
          logo: reader.result as string
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const removeLogo = () => {
    setGreetingData(prev => ({
      ...prev,
      logo: null
    }));
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const downloadImage = async () => {
    if (!greetingCardRef.current) return;
    
    setIsGenerating(true);
    try {
      const dataUrl = await toPng(greetingCardRef.current, {
        quality: 1,
        pixelRatio: 2,
        backgroundColor: '#ffffff'
      });
      
      const link = document.createElement('a');
      link.download = `${selectedTemplate.name}-greeting-${Date.now()}.png`;
      link.href = dataUrl;
      link.click();
    } catch (error) {
      console.error('Error generating image:', error);
      alert('Failed to generate image. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-indigo-50 p-6">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-800 mb-8">Create Greeting Card</h1>
        
        <div className="grid lg:grid-cols-2 gap-8">
          {/* Left Column - Form */}
          <div className="bg-white rounded-2xl shadow-xl p-6 space-y-6">
            {/* Greeting Type Selection */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Select Greeting Type *
              </label>
              <select
                value={greetingData.type}
                onChange={(e) => handleTemplateChange(e.target.value)}
                className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              >
                {GREETING_TEMPLATES.map(template => (
                  <option key={template.id} value={template.id}>
                    {template.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Business Name */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Your Business Name *
              </label>
              <input
                type="text"
                value={greetingData.businessName}
                onChange={(e) => handleInputChange('businessName', e.target.value)}
                placeholder="Enter your business name"
                className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>

            {/* Message */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Message to be sent with the greeting *
              </label>
              <textarea
                value={greetingData.message}
                onChange={(e) => handleInputChange('message', e.target.value)}
                placeholder="Enter your greeting message"
                rows={3}
                className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>

            {/* Logo Upload */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Your Business Logo (Optional)
              </label>
              <div className="flex items-center gap-4">
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleLogoUpload}
                  className="hidden"
                  id="logo-upload"
                />
                <label
                  htmlFor="logo-upload"
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 cursor-pointer transition-colors"
                >
                  Choose Logo
                </label>
                {greetingData.logo && (
                  <button
                    onClick={removeLogo}
                    className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                  >
                    Remove Logo
                  </button>
                )}
              </div>
              {greetingData.logo && (
                <div className="mt-2">
                  <img
                    src={greetingData.logo}
                    alt="Business logo"
                    className="h-16 w-16 object-contain border rounded-lg"
                  />
                </div>
              )}
            </div>

            {/* Refrens Branding Toggle */}
            <div className="flex items-center justify-between">
              <label className="text-sm font-medium text-gray-700">
                Remove Refrens Branding
              </label>
              <button
                onClick={() => handleInputChange('showRefrens', !greetingData.showRefrens)}
                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                  !greetingData.showRefrens ? 'bg-indigo-600' : 'bg-gray-300'
                }`}
              >
                <span
                  className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                    !greetingData.showRefrens ? 'translate-x-6' : 'translate-x-1'
                  }`}
                />
              </button>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-4 pt-4">
              <button
                onClick={downloadImage}
                disabled={isGenerating}
                className="flex-1 px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed font-medium"
              >
                {isGenerating ? 'Generating...' : 'Download Image'}
              </button>
              <button
                onClick={() => window.print()}
                className="px-6 py-3 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors font-medium"
              >
                Print
              </button>
            </div>
          </div>

          {/* Right Column - Preview and Templates */}
          <div className="space-y-6">
            {/* Live Preview */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h2 className="text-xl font-semibold text-gray-800 mb-4">Live Preview</h2>
              <div 
                ref={greetingCardRef}
                className="relative rounded-xl overflow-hidden shadow-lg aspect-[4/3]"
                style={{
                  backgroundImage: `url(${selectedTemplate.background})`,
                  backgroundSize: 'cover',
                  backgroundPosition: 'center'
                }}
              >
                {/* Overlay Gradient */}
                <div className={`absolute inset-0 bg-gradient-to-br ${selectedTemplate.gradient} opacity-60`} />
                
                {/* Content */}
                <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-white">
                  {/* Logo */}
                  {greetingData.logo && (
                    <img
                      src={greetingData.logo}
                      alt="Logo"
                      className="h-16 w-16 object-contain mb-4 rounded-full bg-white/20 p-2"
                    />
                  )}
                  
                  {/* Greeting Text */}
                  <div className="text-center space-y-2">
                    <h1 className="text-4xl font-bold drop-shadow-lg">
                      {selectedTemplate.name}
                    </h1>
                    <p className="text-lg drop-shadow-md max-w-md">
                      {greetingData.message}
                    </p>
                  </div>
                  
                  {/* Business Name */}
                  <div className="absolute bottom-12 left-0 right-0 text-center">
                    <p className="text-xl font-semibold drop-shadow-lg">
                      {greetingData.businessName}
                    </p>
                  </div>
                  
                  {/* Refrens Branding */}
                  {greetingData.showRefrens && (
                    <div className="absolute bottom-4 right-4 text-xs opacity-75">
                      Proud Member of Refrens.com
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Template Previews */}
            <div className="bg-white rounded-2xl shadow-xl p-6">
              <h2 className="text-xl font-semibold text-gray-800 mb-4">Select Template</h2>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {GREETING_TEMPLATES.map((template) => (
                  <button
                    key={template.id}
                    onClick={() => handleTemplateChange(template.id)}
                    className={`relative rounded-lg overflow-hidden aspect-square group ${
                      selectedTemplate.id === template.id ? 'ring-4 ring-indigo-600' : ''
                    }`}
                  >
                    <img
                      src={template.background}
                      alt={template.name}
                      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
                    />
                    <div className={`absolute inset-0 bg-gradient-to-br ${template.gradient} opacity-50`} />
                    <div className="absolute inset-0 flex items-center justify-center">
                      <span className="text-white font-medium text-sm text-center px-2">
                        {template.name}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GreetingsPage;